import { enquirySchema as en } from "@/lib/enquiry";
// Each language's form sends its own option labels and gets its own error messages.
// These copies are generated by scripts/i18n-build.mjs before dev and build.
import { enquirySchema as fr } from "@/.i18n/fr/lib/enquiry";
import { enquirySchema as de } from "@/.i18n/de/lib/enquiry";
import { enquirySchema as es } from "@/.i18n/es/lib/enquiry";

const schemas = { en, fr, de, es } as const;

export async function POST(request: Request) {
  let body: unknown;
  try {
    body = await request.json();
  } catch {
    return Response.json({ ok: false, error: "Invalid JSON" }, { status: 400 });
  }

  const requested = (body as { locale?: unknown } | null)?.locale;
  const schema = typeof requested === "string" && requested in schemas ? schemas[requested as keyof typeof schemas] : en;
  const parsed = schema.safeParse(body);
  if (!parsed.success) {
    const fieldErrors: Record<string, string> = {};
    for (const issue of parsed.error.issues) {
      const key = String(issue.path[0] ?? "form");
      fieldErrors[key] ??= issue.message;
    }
    return Response.json({ ok: false, fieldErrors }, { status: 422 });
  }

  // Bots fill the hidden honeypot; accept silently so they learn nothing.
  if (parsed.data.website) return Response.json({ ok: true });

  const { website: _honeypot, ...enquiry } = parsed.data;
  void _honeypot;
  console.log("[enquiry]", JSON.stringify({ receivedAt: new Date().toISOString(), ...enquiry }));
  // TODO: send to the CRM (e.g. HubSpot/Pipedrive) and notify the team by email.

  return Response.json({ ok: true });
}
